questionvariables.text:
/*random generating probabilities*/
prob_both:rand_with_step(10,30,5);
prob_plasma:prob_both+rand_with_step(10,50,5);
prob_laptop:prob_both+rand_with_step(10,100-prob_plasma-5,5);

/* model answer*/
ta1:(prob_plasma-prob_both) + (prob_laptop-prob_both);

feedbackvariables.text:
/*Node 1: Checking correct answer*/

/*Node 2: Check if answer is not given in decimal form*/
n2_mistake:ta1/100;

/*Node 3: brief description of error*/
n3_mistake:prob_plasma + prob_laptop - prob_both;
